<script setup>
import {computed,ref} from 'vue'
import {Chart as ChartJS,Title,Tooltip,Legend,BarElement,LineElement,PointElement,CategoryScale,LinearScale,ArcElement} from 'chart.js'
import {Bar,Doughnut} from 'vue-chartjs'
import {usePreferredReducedMotion} from '@vueuse/core'
ChartJS.register(Title,Tooltip,Legend,BarElement,LineElement,PointElement,CategoryScale,LinearScale,ArcElement)
const props=defineProps({chart:String}),publicCount=ref(3),reduced=usePreferredReducedMotion();const marketUrl='https://www.survey.iksconsulting.ru/page94048076.html'
const info=computed(()=>props.chart==='market'?{title:'Российский рынок облачных сервисов',subtitle:'IaaS + PaaS + SaaS · млрд рублей',labels:['2023','2024','2025*'],values:[242.7,322.3,416.5],type:'bar',source:'iKS-Consulting · обзор от 11.11.2025',note:'* 2025 — предварительная оценка. Все точки взяты из одной версии обзора.',url:marketUrl}:props.chart==='structure'?{title:'Из чего складывается рынок',subtitle:'Структура оценки за 2025 год · млрд рублей',labels:['IaaS','PaaS','SaaS'],values:[183.1,42.7,190.7],type:'doughnut',source:'iKS-Consulting · обзор от 11.11.2025',note:'Предварительная оценка 2025 года. Проценты в подсказках рассчитаны от суммы 416,5 млрд руб.',url:marketUrl}:{title:'Где разместить десять условных задач',subtitle:'Учебный сценарий · не статистика банков',labels:['Частная среда','Публичная среда'],values:[10-publicCount.value,publicCount.value],type:'doughnut',source:'Авторская интерактивная модель',note:'Единица — одна условная задача, а не сервер или объём данных. Распределение произвольное; правомерность размещения требует отдельной оценки.'})
const data=computed(()=>({labels:info.value.labels,datasets:[{label:info.value.subtitle,data:info.value.values,backgroundColor:['#c8ff3d','#22d3ee','#ff6b4a'],borderColor:'#111619',borderWidth:info.value.type==='bar'?0:8,borderRadius:info.value.type==='bar'?5:0,maxBarThickness:100}]}))
const options=computed(()=>({responsive:true,maintainAspectRatio:false,animation:reduced.value==='reduce'?false:{duration:900},plugins:{legend:{display:info.value.type!=='bar',position:'bottom',labels:{color:'#dfe5df',font:{family:'Manrope',size:13},padding:20}},tooltip:{backgroundColor:'#f1f2e9',titleColor:'#10150a',bodyColor:'#10150a',padding:14,callbacks:{label:c=>`${c.label}: ${Number(c.raw).toLocaleString('ru-RU')}${props.chart==='structure'?' млрд руб. · '+(Number(c.raw)/416.5*100).toFixed(1)+'%':props.chart==='market'?' млрд руб.':' задач'}`}}},...(info.value.type==='bar'?{scales:{x:{grid:{display:false},ticks:{color:'#c2cbc4',font:{size:14}}},y:{beginAtZero:true,grid:{color:'#ffffff0d'},ticks:{color:'#9ca9a0'}}}}:{cutout:'68%'})}))
</script><template><figure class="chart-block"><p class="eyebrow">ДАННЫЕ / ИНТЕРАКТИВ</p><h3>{{info.title}}</h3><p class="chart-subtitle">{{info.subtitle}}</p><label v-if="chart==='workloads'" class="scenario-control">Задач в публичной среде: <b>{{publicCount}} из 10</b><input v-model.number="publicCount" type="range" min="0" max="10" step="1"></label><div class="chart-canvas"><Bar v-if="info.type==='bar'" :data="data" :options="options" :aria-label="info.title"/><Doughnut v-else :data="data" :options="options" :aria-label="info.title"/></div><dl class="chart-values"><div v-for="(label,i) in info.labels"><dt>{{label}}</dt><dd>{{info.values[i].toLocaleString('ru-RU')}}</dd></div></dl><figcaption><p>{{info.note}}</p><a v-if="info.url" :href="info.url" target="_blank" rel="noopener noreferrer">{{info.source}} ↗</a><span v-else>{{info.source}}</span></figcaption></figure></template>
